sdk.code:
import boto3
dynamodb = boto3.resource('dynamodb')
table = dynamodb.create_table(
    TableName='AccountTransactionData',
    KeySchema=[
        {'AttributeName': 'AccountId', 'KeyType': 'HASH'},
        {'AttributeName': 'TransactionDate', 'KeyType': 'RANGE'}
    ],
    AttributeDefinitions=[
        {'AttributeName': 'AccountId', 'AttributeType': 'S'},
        {'AttributeName': 'TransactionDate', 'AttributeType': 'S'}
    ],
    BillingMode='PAY_PER_REQUEST',
    SSESpecification={'Enabled': True, 'SSEType': 'KMS'}
)

terraform.code:
resource "aws_dynamodb_table" "account_transaction_table" {
  name           = "AccountTransactionData"
  hash_key       = "AccountId"
  range_key      = "TransactionDate"
  billing_mode   = "PAY_PER_REQUEST"
  attribute {
    name = "AccountId"
    type = "S"
  }
  attribute {
    name = "TransactionDate"
    type = "S"
  }
  server_side_encryption {
    enabled = true
    kms_key_arn = aws_kms_key.dynamodb_key.arn
  }
}

